{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Clinical psychotherapy services and membership model offering ongoing support, short-term pathways, and focused packages. Confidential, evidence-informed care.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="page-home">
  <header class="site-header">
    <div class="container">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Primary">
        <a href="/about.html">Practice</a>
        <a href="/specialties.html">Focus Areas</a>
        <a href="/approach.html">Method</a>
        <a href="/fees.html">Investment</a>
        <a href="/faq.html">FAQ</a>
        <a class="cta" href="/book.html">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
      <button class="mobile-toggle" aria-expanded="false" aria-label="Open navigation">☰</button>
    </div>
  </header>

  <main>
    <!-- hero -->
    <section class="hero">
      <svg class="hero-pattern" viewBox="0 0 800 200" preserveAspectRatio="none" aria-hidden="true">
        <defs>
          <pattern id="p" width="40" height="40" patternUnits="userSpaceOnUse">
            <rect width="40" height="40" fill="#f7f9fb"></rect>
            <path d="M0 20h40M20 0v40" stroke="#e6eef5" stroke-width="1"/>
          </pattern>
        </defs>
        <rect width="100%" height="100%" fill="url(#p)"></rect>
      </svg>
      <div class="container hero-inner">
        <div class="hero-copy">
          <h1>{{BUSINESS_NAME}}</h1>
          <p class="lead">A steady clinical membership and short-term pathways for adults seeking clearer next steps and safer self-understanding.</p>
          <p class="meta">Confidential care in {{CITY}}, {{STATE}} • Sessions by appointment • Membership and focused packages</p>
          <div class="hero-actions">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn quiet" href="/contact.html">Contact the practice</a>
          </div>
        </div>
        <aside class="hero-aside">
          <div class="quick-card">
            <h4>Phone</h4>
            <a href="tel:{{PHONE}}">{{PHONE}}</a>
            <h4>Email</h4>
            <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>
          </div>
        </aside>
      </div>
    </section>

    <!-- myth vs truth -->
    <section class="myth-vs-truth container" id="myth">
      <h2>Everyday ideas we meet — and what the work actually looks like</h2>
      <div class="grid-2">
        <div class="card myth">
          <h3>Myth</h3>
          <p>Therapy always means months of weekly long sessions and big upheaval.</p>
        </div>
        <div class="card truth">
          <h3>What we offer</h3>
          <p>Tailored options: an ongoing membership for steady support, and short, focused packages for clearer aims — both aim to be practical and collaborative.</p>
        </div>
      </div>
    </section>

    <!-- pillars -->
    <section class="pillars container">
      <h2>How I structure the work</h2>
      <div class="pillar-list">
        <article>
          <h3>Membership continuity</h3>
          <p>Regular sessions at a predictable cadence to sustain progress, with priority scheduling and flexible check-ins.</p>
        </article>
        <article>
          <h3>Focused packages</h3>
          <p>Short-term, goal-oriented bundles for decision points, life transitions, or concentrated skill-building.</p>
        </article>
        <article>
          <h3>Collaborative planning</h3>
          <p>Each plan begins with shared goals, clear boundaries, and regular reviews so we adjust what helps most.</p>
        </article>
      </div>

      <!-- Pricing Comparator -->
      <div class="pricing-comparator" aria-hidden="false">
        <h4>Compare costs</h4>
        <div class="toggle" role="tablist" aria-label="Pricing frequency">
          <button class="freq active" data-frequency="monthly">Monthly</button>
          <button class="freq" data-frequency="package">Package</button>
        </div>
        <div class="prices">
          <div class="price-item">
            <h5>Membership</h5>
            <div class="amount" data-monthly="120" data-package="1200">$<span class="num">120</span></div>
            <p class="note">Regular one-on-one sessions + scheduling priority</p>
          </div>
          <div class="price-item">
            <h5>Focused Package (6 sessions)</h5>
            <div class="amount" data-monthly="95" data-package="540">$<span class="num">540</span></div>
            <p class="note">Short-term, targeted support with a clear endpoint</p>
          </div>
        </div>
      </div>

    </section>

    <!-- case notes / Proof Gallery -->
    <section class="case-notes container" id="testimonials">
      <h2>What clients share</h2>
      <p class="intro">Reflections from people who chose ongoing or package work. Names anonymized; experiences are individual and not guarantees.</p>

      <div class="proof-gallery">
        <div class="testimonials" aria-live="polite">
          <blockquote class="testimonial active" data-index="0">
            <p>"Regular sessions have helped me keep a smaller set of problems from growing into crises. The membership gives continuity without pressure."</p>
            <cite>— A client in {{CITY}}</cite>
          </blockquote>
          <blockquote class="testimonial" data-index="1">
            <p>"The six-session package gave me a focused plan for a tough transition. We set clear goals and measured what changed."</p>
            <cite>— Someone who completed a package</cite>
          </blockquote>
          <blockquote class="testimonial" data-index="2">
            <p>"I appreciated a clinician who named limits and safety plans clearly. That made sessions feel safer and more useful."</p>
            <cite>— Local resident</cite>
          </blockquote>
        </div>

        <div class="badges">
          <div class="badge" data-tip="Licensed clinician, state board" tabindex="0">LIC<span class="tooltip">Licensed clinician, state board</span></div>
          <div class="badge" data-tip="10+ years clinical practice" tabindex="0">10y<span class="tooltip">10+ years clinical practice</span></div>
          <div class="badge" data-tip="Specialized training in trauma-informed care" tabindex="0">TRA<span class="tooltip">Training in trauma-informed approaches</span></div>
        </div>

        <div class="gallery-controls">
          <button class="prev" aria-label="Previous testimonial">◀</button>
          <button class="pause" aria-pressed="false">Pause</button>
          <button class="next" aria-label="Next testimonial">▶</button>
        </div>
      </div>

    </section>

    <!-- FAQ (short) -->
    <section class="faq container" id="faq">
      <h2>Common questions</h2>
      <dl>
        <dt>How does the membership work?</dt>
        <dd>Members schedule at a regular cadence that we choose together. The membership includes priority booking and periodic plan reviews. It is not an emergency or crisis service.</dd>

        <dt>Are sessions confidential?</dt>
        <dd>Yes. Clinical notes and communications are held in confidence within the limits of law and ethical practice. I will explain the exact boundaries at intake.</dd>

        <dt>What if I need immediate help?</dt>
        <dd>This practice does not provide crisis or emergency services. If you are in imminent danger or need urgent help, contact local emergency services or a crisis line immediately.</dd>
      </dl>
    </section>

    <!-- CTA -->
    <section class="cta container" aria-labelledby="cta-heading">
      <h2 id="cta-heading">Interested in a conversation?</h2>
      <p>If you'd like to explore fit, scheduling, or whether membership or a short package is right, reach out for a brief consult.</p>
      <div class="cta-actions">
        <a class="btn primary" href="{{PRIMARY_CTA_URL}}">Start a brief consult</a>
        <a class="btn quiet" href="/contact.html">Email: {{EMAIL}}</a>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="container">
      <p>&copy; <span id="year"></span> {{BUSINESS_NAME}} • Private practice, {{CITY}}, {{STATE}}</p>
      <nav class="footer-nav">
        <a href="/about.html">Practice</a>
        <a href="/fees.html">Investment</a>
        <a href="/contact.html">Contact</a>
      </nav>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
