{"path":"assets/css/styles.css","content":"/* Minimal, self-contained stylesheet */
:root{--bg:#ffffff;--muted:#6b7280;--accent:#2b6cb0;--soft:#f5f8fb;--card:#fbfdff}
*{box-sizing:border-box}
body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;margin:0;color:#0f172a;background:var(--bg);line-height:1.45}
.container{max-width:980px;margin:0 auto;padding:24px}
.site-header{background:linear-gradient(180deg,#ffffff 0%,#f8fbff 100%);border-bottom:1px solid #e6eef5}
.site-header .container{display:flex;align-items:center;gap:16px}
.brand{font-weight:700;color:var(--accent);text-decoration:none;font-size:1.15rem}
.main-nav{margin-left:auto;display:flex;gap:14px;align-items:center}
.main-nav a{color:#274155;text-decoration:none;padding:8px}
.main-nav .cta{background:var(--accent);color:white;padding:8px 12px;border-radius:6px}
.mobile-toggle{display:none}
.hero{position:relative;padding:36px 0}
.hero-pattern{position:absolute;inset:0;width:100%;height:120px;opacity:1;pointer-events:none}
.hero-inner{display:flex;gap:24px;align-items:flex-start}
.hero-copy{flex:1}
.hero-copy h1{margin:0 0 8px;font-size:1.9rem;color:#07203a}
.lead{margin:0 0 12px;color:#234052}
.meta{margin:8px 0;color:var(--muted);font-size:0.95rem}
.hero-actions .btn{display:inline-block;margin-right:8px;text-decoration:none}
.btn{border-radius:8px;padding:10px 14px;font-weight:600}
.btn.primary{background:var(--accent);color:white}
.btn.quiet{background:transparent;border:1px solid #e6eef5;color:#274155}
.hero-aside{width:220px}
.quick-card{background:var(--card);padding:14px;border-radius:8px;border:1px solid #eaefef}
.h2,.pillars h2{font-size:1.25rem}
.myth-vs-truth{padding-top:18px}
.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.card{background:#fff;padding:16px;border-radius:8px;border:1px solid #eef5fb}
.truth{background:linear-gradient(180deg,#fbfdff,#f7fbff)}
.pillars .pillar-list{display:flex;gap:12px;margin-top:12px}
.pillar-list article{flex:1;background:var(--card);padding:14px;border-radius:8px;border:1px solid #e9f1f8}
.pricing-comparator{margin-top:18px;background:#fff;padding:12px;border-radius:10px;border:1px solid #eef6fb}
.toggle{display:inline-flex;border-radius:8px;overflow:hidden;border:1px solid #e6eef5}
.toggle .freq{padding:8px 12px;background:transparent;border:0;cursor:pointer}
.toggle .freq.active{background:var(--accent);color:white}
.prices{display:flex;gap:12px;margin-top:12px}
.price-item{flex:1;padding:12px;border-radius:8px;background:linear-gradient(180deg,#fff,#fbfdff);border:1px solid #eef6fb}
.amount{font-size:1.4rem;font-weight:700;color:#102a43}
.num{display:inline-block;min-width:40px;text-align:right}
.case-notes{padding-top:18px}
.proof-gallery{display:grid;grid-template-columns:2fr 1fr;gap:18px;align-items:start}
.testimonials{background:var(--soft);padding:16px;border-radius:8px;border:1px solid #e7f0f7;min-height:120px;position:relative}
.testimonial{display:none}
.testimonial.active{display:block}
.badges{display:flex;flex-direction:column;gap:8px}
.badge{background:#fff;border:1px solid #e6eef5;padding:8px;border-radius:6px;width:64px;text-align:center;font-weight:700;cursor:default;position:relative}
.badge .tooltip{visibility:hidden;opacity:0;position:absolute;left:calc(100% + 8px);top:50%;transform:translateY(-50%);background:#083344;color:#fff;padding:8px;border-radius:6px;white-space:nowrap;transition:opacity .18s ease;z-index:10}
.badge:hover .tooltip,.badge:focus .tooltip{visibility:visible;opacity:1}
.gallery-controls{display:flex;gap:8px;align-items:center;margin-top:8px}
.faq dl{background:#fff;padding:12px;border-radius:8px;border:1px solid #eef6fb}
.faq dt{font-weight:700;margin-top:8px}
.cta{margin:24px 0;padding:18px;background:linear-gradient(180deg,#f8fbff,#ffffff);border-radius:10px;border:1px solid #e6f1fb}
.site-footer{border-top:1px solid #e6eef5;padding:18px 0;margin-top:24px}
.site-footer .container{display:flex;justify-content:space-between;align-items:center}
@media(max-width:880px){
  .hero-inner{flex-direction:column}
  .proof-gallery{grid-template-columns:1fr}
  .pillars .pillar-list{flex-direction:column}
  .grid-2{grid-template-columns:1fr}
  .main-nav{display:none}
  .mobile-toggle{display:block;margin-left:auto}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Basic interactive behaviors: mobile nav, rotating testimonials, badges tooltips handled by CSS, pricing comparator
  document.addEventListener('DOMContentLoaded',function(){
    // year
    var y=document.getElementById('year'); if(y) y.textContent=new Date().getFullYear();

    // mobile nav
    var mt=document.querySelector('.mobile-toggle');
    var nav=document.querySelector('.main-nav');
    if(mt && nav){
      mt.addEventListener('click',function(){
        var open = this.getAttribute('aria-expanded') === 'true';
        this.setAttribute('aria-expanded', String(!open));
        nav.style.display = open ? 'none' : 'flex';
      });
    }

    // Testimonials rotation
    var testimonials = document.querySelectorAll('.testimonial');
    var nextBtn = document.querySelector('.gallery-controls .next');
    var prevBtn = document.querySelector('.gallery-controls .prev');
    var pauseBtn = document.querySelector('.gallery-controls .pause');
    var current = 0;
    var interval = 6000;
    var timer = null;

    function showTest(i){
      testimonials.forEach(function(t){t.classList.remove('active');});
      var t = testimonials[i]; if(t) t.classList.add('active');
      current = i;
    }
    function next(){ showTest((current+1)%testimonials.length); }
    function prev(){ showTest((current-1+testimonials.length)%testimonials.length); }
    function start(){ stop(); timer=setInterval(next, interval); pauseBtn && pauseBtn.setAttribute('aria-pressed','false'); }
    function stop(){ if(timer){clearInterval(timer); timer=null;} pauseBtn && pauseBtn.setAttribute('aria-pressed','true'); }

    if(testimonials.length){ start(); }
    if(nextBtn) nextBtn.addEventListener('click', function(){ next(); stop(); });
    if(prevBtn) prevBtn.addEventListener('click', function(){ prev(); stop(); });
    if(pauseBtn) pauseBtn.addEventListener('click', function(){ if(timer) stop(); else start(); });

    // Keyboard accessibility for testimonials
    document.querySelectorAll('.badge').forEach(function(b){
      b.addEventListener('keydown',function(e){ if(e.key==='Enter' || e.key===' ') { e.preventDefault(); this.querySelector('.tooltip') && (this.querySelector('.tooltip').style.visibility='visible'); }});
    });

    // Pricing comparator with animated numbers
    var freqButtons = document.querySelectorAll('.pricing-comparator .freq');
    var priceItems = document.querySelectorAll('.pricing-comparator .price-item');
    function animateNumber(el, from, to){
      var start = null; var duration = 420; from = Number(from); to = Number(to);
      function step(ts){
        if(!start) start = ts; var progress = Math.min((ts - start) / duration,1);
        var val = Math.round(from + (to - from) * progress);
        el.textContent = val;
        if(progress < 1) requestAnimationFrame(step);
      }
      requestAnimationFrame(step);
    }
    freqButtons.forEach(function(btn){
      btn.addEventListener('click', function(){
        freqButtons.forEach(function(b){b.classList.remove('active');});
        this.classList.add('active');
        var freq = this.getAttribute('data-frequency');
        priceItems.forEach(function(item){
          var span = item.querySelector('.num');
          var from = Number(span.textContent) || 0;
          var to = Number(item.getAttribute('data-' + freq));
          animateNumber(span, from, to);
        });
      });
    });

    // Initialize displayed numbers to monthly
    var initBtn = document.querySelector('.pricing-comparator .freq.active');
    if(initBtn){ initBtn.click(); }
  });
})();"} 
